final class AssignSubjectTaxonomySubjectsServiceTest extends TestCase { public function testReplacesOnlyValidatedActiveTaxonomyLinks():void{$subjects=new class implements SubjectRepositoryInterface{public function save(Subject $subject):void{}public function exists(string $id):bool{return $id==='local';}public function existsForSyllabus(string $id,string $syllabusId):bool{return false;}public function listForSyllabus(string $syllabusId):array{return[];}};$taxonomy=new class implements TaxonomySubjectRepositoryInterface{public function save(TaxonomySubject $subject):void{}public function findById(string $id):?TaxonomySubject{return $id==='canonical'?new TaxonomySubject('canonical',null,'Redes','redes',null,0,true):null;}public function findByParentAndSlug(?string $parentId,string $slug):?TaxonomySubject{return null;}public function list(int $offset,int $limit):array{return[];}public function hasChildren(string $subjectId):bool{return false;}public function count():int{return 0;}public function ancestorIds(string $subjectId):array{return[];}};$assignments=new class implements SubjectTaxonomyAssignmentRepositoryInterface{public array $ids=[];public function replaceForSubject(string $subjectId,array $taxonomySubjectIds):void{$this->ids=$taxonomySubjectIds;}public function listTaxonomySubjectIds(string $subjectId):array{return[];}};$transaction=new class implements TransactionManagerInterface{public function transactional(callable $callback):mixed{return$callback();}};(new AssignSubjectTaxonomySubjectsService($subjects,$taxonomy,$assignments,$transaction))->assign(new AssignSubjectTaxonomySubjectsRequestDto('local',['canonical','canonical']));self::assertSame(['canonical'],$assignments->ids);}}
